      {
        "id": "CVE-2026-24858",
        "product": "FortiOS, FortiManager, FortiAnalyzer (FortiCloud SSO)",
        "status": "patched",
        "note": "Mitigation: admin login through FortiCloud SSO stays off at device registration (admin-forticloud-sso-login disable). Permanent fix: the go-live baseline is at or above the fixed versions in advisory FG-IR-26-060 (FortiOS 7.4.11 or 7.6.6; FortiManager and FortiAnalyzer 7.4.10 or 7.6.6). In CISA KEV since 2026-01-27."
      }
